from client import save
from tests.test_client import MemoryTransport
for value, expected in [('  Ada  ', 'Ada'), ('Ada Lovelace', 'Ada Lovelace'), ('', ''), (' \\t\\n', ''), ('\\tAda\\n', 'Ada'), ('Ada  Lovelace', 'Ada  Lovelace')]:
    transport=MemoryTransport()
    result=save(transport,value)
    assert transport.request==('/settings', {'display_name':expected})
    assert result=={'ok':True}
    print(repr(value), '->', repr(transport.request[1]['display_name']))
